import jax.numpy as jnp

def candidate(coefficients, x):
    p = [c for c in coefficients]
    x_pow = x
    while len(p) > 1:
        next_p = []
        for i in range(0, len(p) - 1, 2):
            next_p.append(p[i] + p[i + 1] * x_pow)
        if len(p) % 2 == 1:
            next_p.append(p[-1])
        p = next_p
        if len(p) > 1:
            x_pow = x_pow * x_pow
    return p[0]
